import 'package:flutter/material.dart';import '../../Features/Favorite/presentation/pages/favorite_screen.dart';import '../../Features/Global/Authentication/presentation/pages/authentication_screen.dart';import '../../Features/Cart/presentation/pages/cart_screen.dart';import '../../Features/Global/Boarding/presentation/pages/boarding_screen.dart';import '../../Features/Global/Splash/Pages/splash_screen.dart';import '../../Features/Main/presentation/pages/main_screen.dart';import '../../Features/ModelImages/presentation/pages/3d_screen.dart';import '../../Features/ModelImages/presentation/pages/aR_view_screen.dart';import '../../Features/Research/presentation/pages/search_screen.dart';import 'route_name.dart';class AppRouteBuilders {  static Route<dynamic> generateRoute(RouteSettings settings) {    switch (settings.name) {      case AppRoutes.splash:        return _defaultPageRoute(const SplashScreen());      case AppRoutes.boarding:        return _defaultPageRoute(const BoardingScreen());      case AppRoutes.authentication:        return _defaultPageRoute(const AuthenticationScreen());      case AppRoutes.main:        return _defaultPageRoute(const MainScreen());      case AppRoutes.search:        return _defaultPageRoute(const SearchScreen());      case AppRoutes.cart:        return _defaultPageRoute(const CartScreen());      case AppRoutes.favorite:        return _defaultPageRoute(const FavoriteScreen());        case AppRoutes.screen3D:        return _defaultPageRoute(const Screen3D());        case AppRoutes.aRViewScreen:        return _defaultPageRoute(const ARViewScreen());      default:        return _errorRoute('No route defined for "${settings.name}"');    }  }  static MaterialPageRoute<dynamic> _defaultPageRoute(Widget screen) {    return MaterialPageRoute(builder: (_) => screen);  }  static Route<dynamic> _errorRoute(String message) {    return MaterialPageRoute(      builder: (_) => Scaffold(        body:            Center(child: Text(message, style: const TextStyle(fontSize: 18))),      ),    );  }}